<template><div class="page-card"><div class="toolbar"><el-button @click="load">刷新</el-button><span class="muted">发布版本由 CI/CD 导入，不在网页中修改镜像摘要。</span></div><el-table :data="rows"><el-table-column prop="version" label="版本" width="130"/><el-table-column prop="image_repository" label="镜像仓库" min-width="240"/><el-table-column prop="image_digest" label="Digest" min-width="300" show-overflow-tooltip/><el-table-column prop="git_commit" label="Commit" width="150"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="发布时间" width="190"><template #default="s">{{ $dt(s.row.published_at) }}</template></el-table-column><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="detail(s.row)">入口</el-button></template></el-table-column></el-table><el-drawer v-model="visible" title="SpiderEntry 清单" size="70%"><el-table :data="current.entries||[]"><el-table-column prop="task_name" label="任务入口" min-width="220"/><el-table-column prop="image_profile" label="镜像类型" width="110"/><el-table-column prop="default_timeout_seconds" label="默认超时" width="120"/><el-table-column label="所需资源" min-width="250"><template #default="s">{{ s.row.required_resources?.join(', ') || '无' }}</template></el-table-column><el-table-column prop="description" label="说明" min-width="220"/></el-table></el-drawer></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import api from'../api';const rows=ref([]),visible=ref(false),current=reactive({});async function load(){rows.value=(await api.get('/spider-releases')).data}async function detail(row){Object.assign(current,(await api.get(`/spider-releases/${row.release_id}`)).data);visible.value=true}onMounted(load)</script>
